steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query { issue(identifier: \"WEB-12\") { id identifier title url comments(first: 50) { nodes { id body createdAt user { name email } replyTo { id } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query { issues(filter: { identifier: { eq: \"WEB-12\" } }, first: 1) { nodes { id identifier title url } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query { issues(filter: { search: { query: \"WEB-12\" } }, first: 5) { nodes { id identifier title url } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query { issue(id: \"WEB-12\") { id identifier title url } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "query { issue(id: \"WEB-12\") { id comments(first: 50) { nodes { id body createdAt user { name email } } } } }"
  }'
